import scalax.transducers._       // ships map/filter/take as transducers

// Transducer[A, B] is a function Reducer[B, _] => Reducer[A, _] (rank-2);
// it never sees its source or its sink
val xf: Transducer[Int, Int] = filter[Int](_ % 2 == 0) andThen map[Int, Int](x => x * x)
val composed = xf andThen take[Int](3)          // transducers compose like functions
// application picks the destination: composed.into[List].run(src) / .reduce(plus, 0).run(src)
